        ExportOpNonMaximumSuppression(m);
        ExportOpReformat(m);
        ExportOpResize(m);
        ExportOpCustomCrop(m);
        ExportOpNormalize(m);
        ExportOpConvertTo(m);
        ExportOpPadAndStack(m);
        ExportOpCopyMakeBorder(m);
        ExportOpRotate(m);
